'use strict';

// MODULES //

var flushBlock = require( './flush_block.js' );


// MAIN //

/**
* Extracts blocks from source string.
*
* @private
* @param {string} src - source string
* @param {string} file - file path
* @returns {Array<Object>} blocks
*
* @example
* var src = '/**\\n* @example\\n* int x = 0;\\n*' + '/';
* extractCSource( src, '/path/to/file.c' );
*/
function extractCSource( src, file ) {
	var blockLines;
	var inDocBlock;
	var cleanLine;
	var inExample;
	var blocks;
	var lines;
	var line;
	var out;
	var i;

	blocks = [];

	if ( /^\s*\/\/\s*stdlib-c-doctest\s+disable-file\b/m.test( src ) ) {
		return blocks;
	}

	lines = src.split( '\n' );
	inDocBlock = false;
	inExample = false;
	blockLines = [];

	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];

		if ( inDocBlock ) {
			if ( /^\s*\*\//.test( line ) ) {
				if ( inExample ) {
					flushBlock( blockLines, lines, i, blocks, file );
				}
				inDocBlock = false;
				inExample = false;
			} else if ( /^\s*\*\s*@example/.test( line ) ) {
				if ( inExample ) {
					flushBlock( blockLines, lines, i, blocks, file );
				}
				inExample = true;
				blockLines = [];
			} else if ( inExample ) {
				// Replace leading `* ` with `  ` to preserve column offset
				cleanLine = line.replace( /^(\s*)\*( ?)/, '$1  ' );
				out = {
					'text': cleanLine,
					'line': i + 1
				};
				blockLines.push( out );
			}
		} else if ( /^\s*\/\*\*/.test( line ) ) {
			inDocBlock = true;
			inExample = false;
			blockLines = [];
		}
	}

	return blocks;
}


// EXPORTS //

module.exports = extractCSource;
